#!/usr/bin/env bash
# Agent Node standalone installer; contains only the committed project archive.
set -Eeuo pipefail
#!/usr/bin/env bash
# Shared by the source entry and embedded in the standalone download.
choose_install_role(){
  INSTALL_ROLE=server
  INSTALL_ROLE_EXPLICIT=no
  case "${1:-}" in
    --server) INSTALL_ROLE_EXPLICIT=yes ;;
    --control) INSTALL_ROLE=control; INSTALL_ROLE_EXPLICIT=yes ;;
    --gateway) INSTALL_ROLE=gateway; INSTALL_ROLE_EXPLICIT=yes ;;
    '')
      if [[ -t 0 ]]; then
        local choice
        printf '\n选择安装角色：\n 1) 后端（VPS，root 用户）\n 2) 控制端（Linux / WSL，普通用户）\n 3) VPS 控制端＋统一网关（root 用户）\n' >&2
        read -rp '请选择 [1/2/3]：' choice || return 1
        case "$choice" in
          1) INSTALL_ROLE=server ;;
          2) INSTALL_ROLE=control ;;
          3) INSTALL_ROLE=gateway ;;
          *) printf '请输入 1、2 或 3。\n' >&2; return 2 ;;
        esac
      fi
      ;;
  esac
}

choose_install_role "${1:-}"
if [[ "$INSTALL_ROLE_EXPLICIT" == yes ]]; then shift; fi
role="$INSTALL_ROLE"
role_args=(--"$role")
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
  echo '在 root 登录终端运行：新节点安装，已有节点备份程序后更新。订阅登录由用户手动执行。'
  echo '可选参数：--proxy|--no-proxy --tailscale|--no-tailscale'
  echo '程序目录 /opt/agent-node；保留节点密钥、原生认证和代理配置。'
  echo 'Linux 控制端：普通用户运行 bash install.sh --control [--tailscale|--no-tailscale]'
  echo '控制端程序目录 ~/.local/share/agent-node/toolkit；服务由 systemd --user 管理。'
  echo '角色：--server 后端、--control 本地控制端、--gateway VPS 统一网关。'
  echo '网关参数：--config /private/config.json --build /verified/build --domain op.example.com（可选）。'
  echo '--toolkit-only：仅替换已安装的部署工具包，不安装依赖、不重启服务。'
  exit 0
fi
toolkit_only=no
if [[ "${1:-}" == --toolkit-only ]]; then
  toolkit_only=yes
  shift
  (($# == 0)) || { echo '--toolkit-only 不接受其他部署参数。' >&2; exit 1; }
fi
[[ "$(uname -s)" == Linux ]] || { echo '仅支持 Ubuntu/Debian Linux（含 WSL）。' >&2; exit 1; }
if [[ "$role" == server || "$role" == gateway ]]; then
  [[ $EUID -eq 0 && "$HOME" == /root ]] || { echo '请先 sudo -i，使用完整 root 登录环境。控制端请用普通用户加 --control。' >&2; exit 1; }
  install_parent=/opt
  target=/opt/agent-node
  [[ "$role" != gateway ]] || target=/opt/agent-node-gateway
  lock_file=/run/agent-node-install.lock
  [[ "$role" != gateway ]] || lock_file=/run/agent-node-gateway-install.lock
else
  [[ $EUID -ne 0 ]] || { echo '控制端请用普通用户运行，加 --control；不要使用 sudo 启动整个安装脚本。' >&2; exit 1; }
  install_parent="$HOME/.local/share/agent-node"
  target="$install_parent/toolkit"
  mkdir -p "$install_parent"
  lock_file="$install_parent/control-install.lock"
fi
[[ ! -L "$target" ]] || { echo '保留符号链接目标目录，请手动核对。' >&2; exit 1; }
[[ "$toolkit_only" == no || -d "$target" ]] || { echo '尚未安装工具包，请先执行完整安装。' >&2; exit 1; }
if [[ -e "$target" ]]; then
  [[ -f "$target/install.sh" && -f "$target/linux/agent-node.sh" ]] && grep -Fq '# Agent Node:' "$target/linux/agent-node.sh" || { echo '目标目录不是本工具的安装，未覆盖。' >&2; exit 1; }
fi
exec 9>"$lock_file"
flock -n 9 || { echo '另一个安装 / 更新正在运行，请稍后重试。' >&2; exit 1; }
mkdir -p "$install_parent"
staging="$(mktemp -d "$install_parent/.agent-node-install.XXXXXX")"
previous=''
finished=0
cleanup(){
  local code=$?
  if [[ "$finished" == 0 && -n "$previous" && -d "$previous/project" ]]; then
    if [[ -e "$target" ]]; then mv -T "$target" "$previous/failed-program"; fi
    mv -T "$previous/project" "$target"
    echo "更新未完成，已恢复旧程序目录；失败程序保存在 $previous/failed-program。节点状态和系统包由各模块管理。" >&2
  fi
  rm -rf -- "$staging"
  return "$code"
}
trap cleanup EXIT
base64 --decode > "$staging/project.tar.gz" <<'AGENT_NODE_ARCHIVE'
